-- 科研瓶颈与资源分析：把延期、服务缺口、入组困难和资源等待纳入可汇总数据。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研瓶颈事件" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer,
    "项目编号" integer,
    "人员编号" integer,
    "事件类型" varchar(30) NOT NULL,
    "原因代码" varchar(100),
    "标题" varchar(200) NOT NULL,
    "描述" varchar(4000),
    "严重程度" varchar(10) NOT NULL DEFAULT '中',
    "状态" varchar(10) NOT NULL DEFAULT '开放',
    "开始时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "解决时间" timestamp without time zone,
    "等待天数" numeric(10,2),
    "责任人编号" integer,
    "来源类型" varchar(50),
    "来源编号" varchar(200),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研瓶颈事件" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研瓶颈事件_类型" CHECK ("事件类型" IN ('延期原因','方法学服务缺口','入组困难','数据服务等待','资源使用','其他')),
    CONSTRAINT "ck_科研瓶颈事件_严重程度" CHECK ("严重程度" IN ('低','中','高','紧急')),
    CONSTRAINT "ck_科研瓶颈事件_状态" CHECK ("状态" IN ('开放','处理中','已解决','已关闭')),
    CONSTRAINT "ck_科研瓶颈事件_日期" CHECK ("解决时间" IS NULL OR "解决时间" >= "开始时间"),
    CONSTRAINT "ck_科研瓶颈事件_等待天数" CHECK ("等待天数" IS NULL OR "等待天数" >= 0)
);

CREATE INDEX IF NOT EXISTS "ix_科研瓶颈事件_项目状态"
    ON "科研瓶颈事件" ("流程模板编号", "项目编号", "状态", "严重程度");
CREATE INDEX IF NOT EXISTS "ix_科研瓶颈事件_类型原因"
    ON "科研瓶颈事件" ("事件类型", "原因代码", "开始时间");

CREATE TABLE IF NOT EXISTS "科研资源使用记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer,
    "项目编号" integer,
    "人员编号" integer,
    "资源类型" varchar(50) NOT NULL,
    "资源名称" varchar(200) NOT NULL,
    "申请时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "计划开始时间" timestamp without time zone,
    "实际开始时间" timestamp without time zone,
    "实际结束时间" timestamp without time zone,
    "状态" varchar(10) NOT NULL DEFAULT '申请中',
    "数量" numeric(12,2),
    "使用小时" numeric(12,2),
    "等待小时" numeric(12,2),
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研资源使用记录" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研资源使用记录_状态" CHECK ("状态" IN ('申请中','已排期','使用中','已完成','已取消')),
    CONSTRAINT "ck_科研资源使用记录_时间" CHECK ("实际结束时间" IS NULL OR "实际开始时间" IS NULL OR "实际结束时间" >= "实际开始时间"),
    CONSTRAINT "ck_科研资源使用记录_数值" CHECK (("数量" IS NULL OR "数量" >= 0) AND ("使用小时" IS NULL OR "使用小时" >= 0) AND ("等待小时" IS NULL OR "等待小时" >= 0))
);

CREATE INDEX IF NOT EXISTS "ix_科研资源使用记录_资源"
    ON "科研资源使用记录" ("资源类型", "资源名称", "状态", "申请时间");
CREATE INDEX IF NOT EXISTS "ix_科研资源使用记录_项目"
    ON "科研资源使用记录" ("流程模板编号", "项目编号", "状态");

CREATE OR REPLACE VIEW "v_科研瓶颈汇总" AS
SELECT "事件类型", "原因代码", "严重程度", "状态",
       count(*)::bigint AS "事件数",
       round(avg("等待天数")::numeric, 2) AS "平均等待天数",
       max("等待天数") AS "最大等待天数",
       min("开始时间") AS "最早开始时间"
  FROM "科研瓶颈事件"
 GROUP BY "事件类型", "原因代码", "严重程度", "状态";

CREATE OR REPLACE VIEW "v_科研资源使用汇总" AS
SELECT "资源类型", "资源名称", "状态",
       count(*)::bigint AS "申请数",
       coalesce(sum("使用小时"), 0)::numeric(14,2) AS "使用小时",
       coalesce(sum("等待小时"), 0)::numeric(14,2) AS "等待小时",
       round(avg("等待小时")::numeric, 2) AS "平均等待小时"
  FROM "科研资源使用记录"
 GROUP BY "资源类型", "资源名称", "状态";

UPDATE "系统迁移版本"
   SET "版本" = 50,
       "脚本" = '001-050',
       "检查摘要" = '增加科研瓶颈事件、资源使用记录和决策汇总视图'
 WHERE "编号" = 1;

COMMIT;
